    "model": "claude-3-5-sonnet-20240620",
    "max_tokens": 1024,
    "messages": [
        {"role": "user", "content": [
            {"type": "image", "source": {
                "type": "base64",
                "media_type": "' $IMAGE_MEDIA_TYPE '",
                "data": "' $IMAGE_BASE64 '"
            }},
            {"type": "text", "text": "What is in the above image?"}
        ]}
    ]
}'
